export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
const INITIAL_ASSESSMENT_SURCHARGE = 0.1;

/** The MHPCO price list; only the types pinned down by tests so far. */
const BASE_PREMIUMS: Record<string, number | undefined> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));

/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));

const basePremiumFor = (item: Item): number => {
  const basePremium = BASE_PREMIUMS[item.type];
  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
  return basePremium;
};

const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);

const quote = (step: QuoteStep): StepResult => {
  const policyBasePremium = sum(step.items.map(basePremiumFor));
  const afterInitialAssessment = policyBasePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
  return { premium: roundUpToWholeG(afterInitialAssessment + PROCESSING_FEE) };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step);
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

