import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });

      expect(result).toEqual({ results: [{ premium: 5 }] });
    });
    it("a single sword → base premium 100 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("a single amulet → base premium 60 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "amulet" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("a single staff → base premium 80 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "staff" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 93 }] });
    });
    it("a single potion → base premium 40 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "potion" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 49 }] });
    });
    it("a single rune → base premium 25 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 33 }] });
    });
    it("a single moonstone → base premium 25 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 33 }] });
    });
  });

  describe("quote — component building blocks", () => {
    it("2 runes → 50 G base premium (no block)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 60 }] });
    });
    it("3 runes → 60 G base premium (block applies)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium (no block)");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("a cursed sword adds a 50 % risk surcharge to that item's base premium");
    it.todo("a sword with enchantment 5 adds a 30 % high-enchantment surcharge");
    it.todo("a sword with enchantment 4 gets no high-enchantment surcharge");
    it.todo("a cursed sword with enchantment 5 gets both surcharges");
    it.todo(
      "a cursed sword and a plain amulet → policy base 160 G, curse adds 50 G (50 % of the cursed item only) → 210 G before policy modifiers and fee",
    );
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
    it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
    it.todo("every quote carries the 10 % initial assessment surcharge");
    it.todo("the second quote of a scenario receives the 15 % follow-up contract discount");
    it.todo("the first quote of a scenario receives no follow-up contract discount");
    it.todo("a 5 G processing fee is added to every premium at the very end");
  });

  describe("quote — rounding in the MHPCO's favour", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed sword → premium 165 G");
    it.todo(
      "long-standing customer (3 years) second quote, cursed sword enchantment 7 → premium 160 G",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
    it.todo("a 100 G deductible applies once per damaged item");
    it.todo(
      "a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G",
    );
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full then deductible)");
    it.todo(
      "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)",
    );
    it.todo(
      "dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G",
    );
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo(
      "a policy covering a sword and 3 runes → insurance sum 1750 G (the block discount affects the premium only)",
    );
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo(
      "sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G",
    );
    it.todo(
      "second successive claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to the remaining cap)",
    );
  });

  describe("claim — multiple items of the same type", () => {
    it.todo(
      "two swords insured, both damaged → each damage entry is treated separately with its own deductible",
    );
    it.todo(
      "more damage entries of a type than insured (two sword damages, one sword insured) → the claim is rejected",
    );
  });

  describe("claim — rounding in the MHPCO's favour", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("errors", () => {
    it.todo("a quote with an unknown item type (e.g. broomstick) → error, no results");
    it.todo("a claim referencing an item that is not part of the policy → error");
    it.todo("a claim referencing an item with an unknown type → error");
    it.todo("a claim with a damage entry of amount -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes {results} to stdout in step order");
    it.todo("exits with a non-zero status and writes to stderr on an invalid scenario");
  });
});

