/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));

/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));

const basePremiumFor = (item: Item): number => {
  const basePremium = BASE_PREMIUMS[item.type];
  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
  return basePremium;
};

const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);

/** A building block of 3 alike components is offered at a special base premium. */
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const alikeComponentGroups = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

const basePremiumForGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumFor));

const quote = (step: QuoteStep): StepResult => {
  const policyBasePremium = sum(alikeComponentGroups(step.items).map(basePremiumForGroup));
  const afterInitialAssessment = policyBasePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
  return { premium: roundUpToWholeG(afterInitialAssessment + PROCESSING_FEE) };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step);
  throw new Error(`Unsupported step: ${step.op}`);
};

