      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

const basePremiumForGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);

const CURSE_SURCHARGE = 0.5;

/** Item-specific surcharges are levied on the affected item's own base premium. */
const surchargesFor = (item: Item): number =>
  item.cursed ? basePremiumFor(item) * CURSE_SURCHARGE : 0;

const quote = (step: QuoteStep): StepResult => {
  const basePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
  const surcharges = sumOf(step.items, surchargesFor);
  const afterInitialAssessment =
    (basePremium + surcharges) * (1 + INITIAL_ASSESSMENT_SURCHARGE);
  return { premium: roundUpToWholeG(afterInitialAssessment + PROCESSING_FEE) };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step);
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

