const LOYALTY_THRESHOLD_YEARS = 2;

/** The customer as they stand at the moment a particular contract is quoted. */
interface Policyholder {
  customer: Customer;
  isFollowUpContract: boolean;
}

const isLongStanding = ({ customer }: Policyholder): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

const isFollowUpContract = (policyholder: Policyholder): boolean =>
  policyholder.isFollowUpContract;

const alwaysApplies = (): boolean => true;

/** Policy-wide modifiers are levied on the whole policy's base premium. */
const POLICY_MODIFIERS: Modifier<Policyholder>[] = [
  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT },
  { appliesTo: alwaysApplies, rate: INITIAL_ASSESSMENT_SURCHARGE },
  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT },
];

const quote = (step: QuoteStep, policyholder: Policyholder): StepResult => {
  const basePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
