  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
const LOYALTY_DISCOUNT = -0.2;
/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
const INITIAL_ASSESSMENT_SURCHARGE = 0.1;

/** The MHPCO price list; only the types pinned down by tests so far. */
const BASE_PREMIUMS: Record<string, number | undefined> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));

/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));

const basePremiumFor = (item: Item): number => {
  const basePremium = BASE_PREMIUMS[item.type];
  if (basePremium === undefined) throw new Error(`Unknown item type: ${item.type}`);
  return basePremium;
};

const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
  values.reduce((total, value) => total + amountOf(value), 0);

/** A building block of 3 alike components is offered at a special base premium. */
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const alikeComponentGroups = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

const basePremiumForGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);

const HIGH_ENCHANTMENT_THRESHOLD = 5;

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;

/**
 * A modifier raises or lowers the amount it applies to by `rate`, but only for
 * subjects it applies to. Modifiers that apply stack additively.
 */
interface Modifier<Subject> {
  appliesTo: (subject: Subject) => boolean;
  rate: number;
}

const combinedRateOf = <Subject>(
  modifiers: Modifier<Subject>[],
  subject: Subject,
): number => sumOf(modifiers, ({ appliesTo, rate }) => (appliesTo(subject) ? rate : 0));

/** Item-specific modifiers are levied on the affected item's own base premium. */
const ITEM_MODIFIERS: Modifier<Item>[] = [
  { appliesTo: isCursed, rate: CURSE_SURCHARGE },
  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
];

const modifiersFor = (item: Item): number =>
  basePremiumFor(item) * combinedRateOf(ITEM_MODIFIERS, item);

const LOYALTY_THRESHOLD_YEARS = 2;

const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

const alwaysApplies = (): boolean => true;

/** Policy-wide modifiers are levied on the whole policy's base premium. */
const POLICY_MODIFIERS: Modifier<Customer>[] = [
  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT },
  { appliesTo: alwaysApplies, rate: INITIAL_ASSESSMENT_SURCHARGE },
];

const quote = (step: QuoteStep, customer: Customer): StepResult => {
  const basePremium = sumOf(alikeComponentGroups(step.items), basePremiumForGroup);
  const itemModifiers = sumOf(step.items, modifiersFor);
  const policyBasePremium = basePremium + itemModifiers;
  const afterPolicyModifiers =
    policyBasePremium * (1 + combinedRateOf(POLICY_MODIFIERS, customer));
  return { premium: roundUpToWholeG(afterPolicyModifiers + PROCESSING_FEE) };
};

const runStep = (step: Step, customer: Customer): StepResult => {
  if (step.op === "quote") return quote(step, customer);
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});

