const insuranceValueFor = (item: Item): number => {
  const insuranceValue = INSURANCE_VALUES[item.type];
  if (insuranceValue === undefined) throw new Error(`Unknown item type: ${item.type}`);
  return insuranceValue;
};

/** A policy created by a quote step, against which later claims are settled. */
interface Policy {
  items: Item[];
  remainingCap: number;
}

const policyFor = (step: QuoteStep): Policy => ({
  items: step.items,
  remainingCap: sumOf(step.items, insuranceValueFor) * CAP_MULTIPLE_OF_INSURANCE_SUM,
});

const payoutForDamage = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

const claim = (step: ClaimStep, policy: Policy): StepResult => {
  const payout = sumOf(step.incident.damages, payoutForDamage);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

/**
 * Steps are not independent: a quote's premium depends on whether an earlier
 * quote in the same scenario already established a contract, and a claim is
 * settled against the policy an earlier quote created.
 */
export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies = new Map<number, Policy>();
  let hasQuoted = false;

  const results = scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const result = quote(step, {
        customer: scenario.customer,
        isFollowUpContract: hasQuoted,
      });
      policies.set(index, policyFor(step));
      hasQuoted = true;
      return result;
    }

    const policy = policies.get(step.policy);
    if (policy === undefined) throw new Error(`No policy at step ${step.policy}`);
    return claim(step, policy);
  });

  return { results };
};

