/** Damage to a heavily enchanted item is only half reimbursed. */
const HALF_REIMBURSEMENT_THRESHOLD = 8;
const HALF_REIMBURSEMENT_RATE = 0.5;

const isHeavilyEnchanted = (item: Item): boolean =>
  item.enchantment !== undefined && item.enchantment >= HALF_REIMBURSEMENT_THRESHOLD;

const reimbursementRateFor = (item: Item): number =>
  isHeavilyEnchanted(item) ? HALF_REIMBURSEMENT_RATE : 1;

const insuredItemFor = (damage: Damage, policy: Policy): Item => {
  const item = policy.items.find(({ type }) => type === damage.itemType);
  if (item === undefined) throw new Error(`Item not insured: ${damage.itemType}`);
  return item;
};

/** The clause is applied to the damage first; the deductible comes off the result. */
const payoutForDamage = (damage: Damage, policy: Policy): number =>
  damage.amount * reimbursementRateFor(insuredItemFor(damage, policy)) -
  DEDUCTIBLE_PER_DAMAGE;

