const BASE_PREMIUMS: Record<string, number | undefined> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/** What each item is insured for; distinct from what it costs to insure. */
const INSURANCE_VALUES: Record<string, number | undefined> = {
  sword: 1000,
